quests[8425] = { id = 8425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoofedern", description = "Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.\n\nMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.\n\nReist zu dem Versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neu bilden können, damit ich Euch belohnen kann.", sourceObjective = "Bringt die Voodoofedern der Trolle im Versunkenen Tempel zu dem gefallenen Helden der Horde.", progress = "Seid Ihr schon zurück? Zeit ist für mich nicht mehr, was sie einst für mich war, vielleicht habt Ihr ja wirklich schon einen langen Ausflug hinter Euch...", completion = "Endlich kann ich die kalte Berührung von Stahl wieder spüren, auch wenn es nur für einen Moment ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8426] = { id = 8426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, {name}! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, {name}?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
