quests[8431] = { id = 8431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", progress = "Der Kampf um die Warsongschlucht geht weiter, {name}. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", completion = "Gut gemacht, {class}! Ihr habt der Horde geholfen ihr Eigentumsrecht an der Warsongschlucht zu sichern!" }
