quests[8436] = { id = 8436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\nIn der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. {name}, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrecht zu erhalten!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", sourceObjectiveStatus = "unverified-source-field" }
quests[8437] = { id = 8437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\nIn der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. {name}, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrecht zu erhalten!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Habt Ihr Neuigkeiten aus dem Arathibecken, {name}?", completion = "Die Sicherung unserer Ressourcen im Arathibecken ist eine lebenswichtige Aufgabe! Ihr habt sie gut gemeistert, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8438] = { id = 8438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\nIn der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. {name}, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrecht zu erhalten!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", sourceObjectiveStatus = "unverified-source-field" }
quests[8439] = { id = 8439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\nIn der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. {name}, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrecht zu erhalten!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Habt Ihr Neuigkeiten aus dem Arathibecken, {name}?", completion = "Die Sicherung unserer Ressourcen im Arathibecken ist eine lebenswichtige Aufgabe! Ihr habt sie gut gemeistert, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8440] = { id = 8440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", progress = "Der Krieg gegen den Allianzabschaum frisst Unmengen an Ressourcen, {name}! Wir können es uns nicht erlauben, dass uns unsere Vorräte auf dem Höhepunkt der Schlacht ausgehen. Stellt weiterhin sicher, dass das Arathibecken unter unserer Kontrolle bleibt.", completion = "Hervorragende Arbeit, {name}. Solange wir das Arathibecken halten können, werden unsere Nachschublager gut gefüllt sein." }
quests[8441] = { id = 8441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", progress = "Der Krieg gegen den Allianzabschaum frisst Unmengen an Ressourcen, {name}! Wir können es uns nicht erlauben, dass uns unsere Vorräte auf dem Höhepunkt der Schlacht ausgehen. Stellt weiterhin sicher, dass das Arathibecken unter unserer Kontrolle bleibt.", completion = "Hervorragende Arbeit, {name}. Solange wir das Arathibecken halten können, werden unsere Nachschublager gut gefüllt sein." }
