quests[8687] = { id = 8687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Tunnelgräber des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Tunnelgräber des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Tunnelgräber des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Die Silithiden werden ohne ihre Tunnelgräber Schwierigkeiten haben, all die Schäden zu reparieren, die ihre Baustruktur erlitten hat. Ich vermute, dass Ihr nach einer neuen Aufgabe sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8688] = { id = 8688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Windflucht", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[8689] = { id = 8689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleier der unendlichen Weisheit", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Kampftuch der Qiraji, 2 Jaspisgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8690] = { id = 8690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang der aufziehenden Stürme", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 Obsidiangötzen, 5 Tonskarabäen und 5 Goldskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8691] = { id = 8691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuch der behüteten Geheimnisse", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Kampftuch der Qiraji, 2 Alabastergötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, {name}?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, {name}. Möge er Euch vor der üblen Magie der Qiraji schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8692] = { id = 8692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang des endlosen Lebens", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
